MOD = 998244353
n = int(input())
p = list(map(lambda x: int(x) - 1, input().split()))
s = list(input())

def count_valid_configurations(s, p, n):
    valid_configurations = 0
    from itertools import product

    # Generate all possible combinations for '?' in the string
    question_indices = [i for i, char in enumerate(s) if char == '?']
    for combination in product('RL', repeat=len(question_indices)):
        # Create a new configuration based on the current combination
        current_s = s[:]
        for idx, char in zip(question_indices, combination):
            current_s[idx] = char

        # Simulate the spoon-picking process
        sp = [True] * n
        valid = True
        for i in p:
            if current_s[i] == 'R':
                if sp[i]:
                    sp[i] = False
                elif sp[(i + 1) % n]:
                    sp[(i + 1) % n] = False
                else:
                    valid = False
                    break
            elif current_s[i] == 'L':
                if sp[(i + 1) % n]:
                    sp[(i + 1) % n] = False
                elif sp[i]:
                    sp[i] = False
                else:
                    valid = False
                    break

        if valid:
            valid_configurations += 1
            valid_configurations %= MOD

    return valid_configurations

result = count_valid_configurations(s, p, n)
